// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// configPath 返回仓库根下 config/thresholds.json 的路径。
//
// 进程的 cwd 不一定是仓库根——`go test` 会把它设成包目录 inventory/——所以从 cwd 向上
// 找到 go.mod 所在的模块根，再拼 config 路径。找不到模块根时返回空串。
func configPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "config", "thresholds.json")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

// configuredThresholds 读 config/thresholds.json。**每次调用都重新读文件**，运维改完配置
// 立即生效——不需要重启，更不需要重新构建。文件缺失或内容不是 JSON 对象时返回 nil，
// 调用方据此回退默认值。
func configuredThresholds() map[string]int {
	path := configPath()
	if path == "" {
		return nil
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(raw, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// LowStockThreshold 返回这个仓库的低库存阈值：config/thresholds.json 里配了就用配置值，
// 没配的仓库回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := configuredThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}
