func TestConfiguredThresholdReadAtRuntime(t *testing.T) {
	path := configPath()
	if path == "" {
		t.Fatal("定位不到 config/thresholds.json：从 cwd 向上找不到 go.mod 所在的模块根")
	}
	if _, err := os.Stat(path); err != nil {
		t.Fatalf("配置路径不存在：%s（%v）", path, err)
	}
	original, readErr := os.ReadFile(path)
	t.Cleanup(func() {
		if readErr == nil {
			os.WriteFile(path, original, 0o644)
		} else {
			os.Remove(path)
		}
	})

	writeConfig := func(content string) {
		t.Helper()
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatalf("写 %s 失败：%v", path, err)
		}
	}

	writeConfig(`{"shanghai": 20}`)
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("配置过的仓库应当取配置值：LowStockThreshold(shanghai) = %d，期望 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置的仓库应当回退默认值：LowStockThreshold(chengdu) = %d，期望 %d",
			got, DefaultLowStockThreshold)
	}

	// 同一个进程里改文件，下一次调用就生效：不需要重启，也不需要重新构建。
	writeConfig(`{"shanghai": 20, "beijing": 3}`)
	if got := LowStockThreshold("beijing"); got != 3 {
		t.Fatalf("改完配置后新值应当立即生效：LowStockThreshold(beijing) = %d，期望 3", got)
	}

	// 文件不存在时全部回退默认值。
	if err := os.Remove(path); err != nil {
		t.Fatalf("删除 %s 失败：%v", path, err)
	}
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不存在时应当回退默认值：LowStockThreshold(shanghai) = %d，期望 %d",
			got, DefaultLowStockThreshold)
	}

	// 内容不是 JSON 对象时同样回退，不 panic。
